import type { IsoTimestamp, OrgId, ProjectId, UserId } from "./common";
import type { IssuePriority } from "./issue";

/** How often a rule files an issue. Days are calendar days in the rule's zone. */
export type RecurrenceCadence = "daily" | "weekly";

/**
 * A standing instruction that files an ordinary issue on a cadence.
 * `weekday` is the ISO weekday (1 = Monday … 7 = Sunday) and is set only for
 * weekly rules. `startsOn` and `lastOccurrenceOn` are `YYYY-MM-DD` calendar
 * dates in `timezone`, not instants.
 */
export interface RecurringIssue {
  id: string;
  orgId: OrgId;
  projectId: ProjectId;
  title: string;
  priority: IssuePriority;
  assigneeId: UserId | null;
  cadence: RecurrenceCadence;
  weekday: number | null;
  timezone: string;
  startsOn: string;
  lastOccurrenceOn: string | null;
  paused: boolean;
  createdBy: UserId;
  createdAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
}

import { z } from "zod";
import { issuePrioritySchema } from "./issue";
import { orgIdSchema, projectIdSchema, userIdSchema } from "./common";

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True for a real Gregorian `YYYY-MM-DD` date, rejecting overflow such as Feb 30. */
function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (!match) return false;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** True when `Intl` accepts the zone, which is the runtime's IANA set. */
function isKnownIanaTimeZone(timeZone: string): boolean {
  if (timeZone.trim() === "" || timeZone !== timeZone.trim()) return false;
  try {
    Intl.DateTimeFormat("en-US", { timeZone }).format(0);
    return true;
  } catch {
    return false;
  }
}

export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3).max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: z.enum(["daily", "weekly"]),
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z
      .string()
      .refine(isKnownIanaTimeZone, "must be an IANA time zone"),
    startsOn: z
      .string()
      .refine(isCalendarDate, "must be a real YYYY-MM-DD date"),
  })
  .superRefine((value, ctx) => {
    if (value.cadence === "weekly" && value.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "weekday is required when cadence is weekly",
      });
    }
    if (value.cadence === "daily" && value.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "weekday must be null when cadence is daily",
      });
    }
  });

export type CreateRecurringIssueInput = z.input<typeof createRecurringIssueSchema>;

import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const recurringIssues = sqliteTable(
  "recurring_issues",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    title: text("title").notNull(),
    priority: text("priority", {
      enum: ["none", "low", "medium", "high", "urgent"],
    })
      .notNull()
      .default("none"),
    assigneeId: text("assignee_id"),
    cadence: text("cadence", { enum: ["daily", "weekly"] }).notNull(),
    /** ISO weekday, 1 = Monday … 7 = Sunday. Null for a daily rule. */
    weekday: integer("weekday"),
    timezone: text("timezone").notNull(),
    startsOn: text("starts_on").notNull(),
    lastOccurrenceOn: text("last_occurrence_on"),
    paused: integer("paused", { mode: "boolean" }).notNull().default(false),
    createdBy: text("created_by").notNull(),
    ...timestampColumns,
  },
  (table) => [
    index("recurring_issues_org_created_idx").on(table.orgId, table.createdAt),
    index("recurring_issues_paused_idx").on(table.paused),
  ],
);

export type RecurringIssueRow = typeof recurringIssues.$inferSelect;
export type NewRecurringIssueRow = typeof recurringIssues.$inferInsert;

/**
 * Recurring-issue rules. Org-scoped reads stay behind `orgPredicate`; the job
 * sweep is the one cross-tenant read, matching the trial-expiry listing.
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId, ProjectId, UserId } from "@/types/common";
import type { IssuePriority } from "@/types/issue";
import type { RecurrenceCadence, RecurringIssue } from "@/types/recurring-issue";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp } from "./_mappers";
import type { RecurringIssueRow } from "@/server/db/schema/recurring-issues";

export interface InsertRecurringIssueInput {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly title: string;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
  readonly createdBy: UserId;
}

function toRecurringIssue(row: RecurringIssueRow): RecurringIssue {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    projectId: brandId<ProjectId>(row.projectId),
    title: row.title,
    priority: row.priority,
    assigneeId: row.assigneeId === null ? null : brandId<UserId>(row.assigneeId),
    cadence: row.cadence,
    weekday: row.weekday,
    timezone: row.timezone,
    startsOn: row.startsOn,
    lastOccurrenceOn: row.lastOccurrenceOn,
    paused: row.paused,
    createdBy: brandId<UserId>(row.createdBy),
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
  };
}

export async function insertRecurringIssue(
  input: InsertRecurringIssueInput,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority,
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy: input.createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toRecurringIssue(row);
}

export async function findRecurringIssueById(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

/** Creation order: timestamp, then SQLite rowid so same-millisecond inserts stay stable. */
export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), sql`rowid`)
    .all();
  return rows.map(toRecurringIssue);
}

/** Every rule counts toward the plan cap, paused ones included. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/** Cross-tenant sweep for the recurring-issue job. Paused rules are omitted. */
export async function listUnpausedRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt), sql`rowid`)
    .all();
  return rows.map(toRecurringIssue);
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
