 * Files at most one issue per non-paused rule: the latest occurrence whose
 * local midnight has already arrived. Missed days are never back-filled.
 */
import { createLogger } from "@/lib/logger";
import { PermissionDeniedError } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";
import { runJob } from "./types";
import type { JobResult } from "./types";

const logger = createLogger("recurring-issue-job");

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listUnpausedRecurringIssues();

    for (const rule of rules) {
      try {
        const filed = await fileLatestOccurrence(rule, now);
        if (filed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue rule failed", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Returns true when an issue was filed. Expected refusals (quota, a missing
 * project, an archived project) leave the rule untouched. A creator who can
 * no longer file issues pauses the rule instead.
 */
async function fileLatestOccurrence(
  rule: RecurringIssue,
  now: Date,
): Promise<boolean> {
  const occurrence = latestOccurrence(rule, now);
  if (occurrence === null) return false;
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (!project || isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (!creator || creator.status !== "active") {
    await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return false;
  }

  const actor: Actor = {
    userId: creator.userId,
    orgId: rule.orgId,
    role: creator.role,
  };

  const assigneeId = await activeAssignee(rule.orgId, rule.assigneeId);

  try {
    await createIssue(actor, {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${occurrence})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
      return false;
    }
    logger.warn("recurring issue was not filed", {
      recurringIssueId: rule.id,
      reason: error instanceof Error ? error.message : String(error),
    });
    return false;
  }

  await recurringRepo.setLastOccurrenceOn(rule.orgId, rule.id, occurrence);
  return true;
}

async function activeAssignee(
  orgId: OrgId,
  assigneeId: UserId | null,
): Promise<UserId | null> {
  if (assigneeId === null) return null;
  const member = await memberRepo.findMember(orgId, assigneeId);
  if (!member || member.status !== "active") return null;
  return assigneeId;
}

/**
 * The latest cadence day on or after `startsOn` whose local midnight has been
 * reached by `now`. The current local calendar date is that upper bound:
 * local time is already at or past 00:00 on that date, DST included.
 */
function latestOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = localCalendarDate(now, rule.timezone);
  if (today < rule.startsOn) return null;
  if (rule.cadence === "daily") return today;
  if (rule.weekday === null) return null;

  let cursor = today;
  for (let step = 0; step < 7; step += 1) {
    if (cursor < rule.startsOn) return null;
    if (isoWeekday(cursor) === rule.weekday) return cursor;
    cursor = addCalendarDays(cursor, -1);
  }
  return null;
}

function localCalendarDate(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);

  let year = "";
  let month = "";
  let day = "";
  for (const part of parts) {
    if (part.type === "year") year = part.value;
    if (part.type === "month") month = part.value;
    if (part.type === "day") day = part.value;
  }
  if (year === "" || month === "" || day === "") {
    throw new RangeError(`Could not resolve a calendar date in ${timeZone}`);
  }
  return `${year.padStart(4, "0")}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
}

function isoWeekday(ymd: string): number {
  const [year, month, day] = ymd.split("-").map(Number) as [number, number, number];
  const sundayBased = new Date(Date.UTC(year, month - 1, day)).getUTCDay();
  return sundayBased === 0 ? 7 : sundayBased;
}

function addCalendarDays(ymd: string, days: number): string {
  const [year, month, day] = ymd.split("-").map(Number) as [number, number, number];
  const date = new Date(Date.UTC(year, month - 1, day + days));
  const nextYear = String(date.getUTCFullYear()).padStart(4, "0");
  const nextMonth = String(date.getUTCMonth() + 1).padStart(2, "0");
  const nextDay = String(date.getUTCDate()).padStart(2, "0");
  return `${nextYear}-${nextMonth}-${nextDay}`;
}
