import assert from "node:assert/strict";
import { eq } from "drizzle-orm";
import { ZodError } from "zod";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { getDb, members, organizations } from "@/server/db";
import { enqueue, drain, resetQueue } from "@/server/jobs/queue";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as recurringService from "@/server/services/recurring-issue-service";
import { toIsoTimestamp } from "@/types/common";
import { NotFoundError } from "@/server/services/_support";
import {
  createTenant,
  useTemporaryDatabase,
} from "./server/_support/fixtures.ts";

const cleanup = await useTemporaryDatabase();

function base(orgId: string, projectId: string) {
  return {
    orgId,
    projectId,
    title: "Daily triage",
    cadence: "daily" as const,
    timezone: "UTC",
    startsOn: "2026-03-01",
  };
}

// --- schema ---
{
  const daily = createRecurringIssueSchema.parse({
    orgId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
    projectId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
    title: "Daily triage",
    cadence: "daily",
    timezone: "America/New_York",
    startsOn: "2024-02-29",
  });
  assert.equal(daily.priority, "none");
  assert.equal(daily.assigneeId, null);
  assert.equal(daily.weekday, null);

  const weekly = createRecurringIssueSchema.parse({
    orgId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
    projectId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
    title: "Monday planning",
    cadence: "weekly",
    weekday: 1,
    timezone: "UTC",
    startsOn: "2026-03-02",
    priority: "high",
  });
  assert.equal(weekly.weekday, 1);

  for (const startsOn of ["2026-02-30", "2026-02-29", "2026-13-01", "2026-1-01", "03/01/2026"]) {
    assert.equal(
      createRecurringIssueSchema.safeParse({
        ...base("01ARZ3NDEKTSV4RRFFQ69G5FAV", "01ARZ3NDEKTSV4RRFFQ69G5FAV"),
        startsOn,
      }).success,
      false,
      startsOn,
    );
  }
  for (const timezone of ["Not/AZone", "America/NewYork", "utc", "GMT+5", ""]) {
    const parsed = createRecurringIssueSchema.safeParse({
      ...base("01ARZ3NDEKTSV4RRFFQ69G5FAV", "01ARZ3NDEKTSV4RRFFQ69G5FAV"),
      timezone,
    });
    assert.equal(parsed.success, false, timezone);
  }
  assert.equal(
    createRecurringIssueSchema.safeParse({
      ...base("01ARZ3NDEKTSV4RRFFQ69G5FAV", "01ARZ3NDEKTSV4RRFFQ69G5FAV"),
      cadence: "weekly",
    }).success,
    false,
  );
  assert.equal(
    createRecurringIssueSchema.safeParse({
      ...base("01ARZ3NDEKTSV4RRFFQ69G5FAV", "01ARZ3NDEKTSV4RRFFQ69G5FAV"),
      cadence: "weekly",
      weekday: null,
    }).success,
    false,
  );
  assert.equal(
    createRecurringIssueSchema.safeParse({
      ...base("01ARZ3NDEKTSV4RRFFQ69G5FAV", "01ARZ3NDEKTSV4RRFFQ69G5FAV"),
      weekday: 1,
    }).success,
    false,
  );
  assert.equal(
    createRecurringIssueSchema.safeParse({
      ...base("01ARZ3NDEKTSV4RRFFQ69G5FAV", "01ARZ3NDEKTSV4RRFFQ69G5FAV"),
      title: "ab",
    }).success,
    false,
  );
  assert.equal(
    createRecurringIssueSchema.safeParse({
      ...base("01ARZ3NDEKTSV4RRFFQ69G5FAV", "01ARZ3NDEKTSV4RRFFQ69G5FAV"),
      title: "a".repeat(181),
    }).success,
    false,
  );
  assert.equal(
    createRecurringIssueSchema.safeParse({
      ...base("01ARZ3NDEKTSV4RRFFQ69G5FAV", "01ARZ3NDEKTSV4RRFFQ69G5FAV"),
      weekday: 0,
    }).success,
    false,
  );
}

const tenant = await createTenant("alpha", "starter");
const other = await createTenant("beta", "starter");

await assert.rejects(
  () =>
    recurringService.createRecurringIssue(tenant.actors.member, {
      ...base(other.org.id, tenant.project.id),
    }),
  (error: unknown) => error instanceof TenantScopeError,
);

await assert.rejects(
  () =>
    recurringService.createRecurringIssue(tenant.actors.member, {
      ...base(tenant.org.id, tenant.project.id),
      startsOn: "2026-02-30",
    }),
  (error: unknown) => error instanceof ZodError,
);

await assert.rejects(
  () =>
    recurringService.createRecurringIssue(tenant.actors.viewer, {
      ...base(tenant.org.id, tenant.project.id),
    }),
  (error: unknown) => error instanceof PermissionDeniedError,
);

await assert.rejects(
  () =>
    recurringService.createRecurringIssue(tenant.actors.member, {
      ...base(tenant.org.id, tenant.project.id),
      assigneeId: other.userIds.member,
    }),
  (error: unknown) => error instanceof Error && !(error instanceof ZodError),
);

const listedEmpty = await recurringService.listRecurringIssues(
  tenant.actors.viewer,
  tenant.org.id,
);
assert.equal(listedEmpty.length, 0);

const first = await recurringService.createRecurringIssue(tenant.actors.member, {
  ...base(tenant.org.id, tenant.project.id),
  title: "Daily triage",
  priority: "high",
  assigneeId: tenant.userIds.admin,
});
assert.equal(first.paused, false);
assert.equal(first.lastOccurrenceOn, null);
assert.equal(first.createdBy, tenant.userIds.member);
assert.equal(first.priority, "high");
assert.equal(first.weekday, null);

const second = await recurringService.createRecurringIssue(tenant.actors.admin, {
  orgId: tenant.org.id,
  projectId: tenant.project.id,
  title: "Monday planning",
  cadence: "weekly",
  weekday: 1,
  timezone: "America/New_York",
  startsOn: "2026-01-01",
});
assert.equal(second.assigneeId, null);
assert.equal(second.priority, "none");

const third = await recurringService.createRecurringIssue(tenant.actors.owner, {
  ...base(tenant.org.id, tenant.project.id),
  title: "Standup",
  timezone: "UTC",
});

const listed = await recurringService.listRecurringIssues(
  tenant.actors.member,
  tenant.org.id,
);
assert.deepEqual(
  listed.map((rule) => rule.id),
  [first.id, second.id, third.id],
);

await assert.rejects(
  () =>
    recurringService.createRecurringIssue(tenant.actors.member, {
      ...base(tenant.org.id, tenant.project.id),
      title: "One too many",
    }),
  (error: unknown) => error instanceof Error,
);
const stillThree = await recurringService.listRecurringIssues(
  tenant.actors.owner,
  tenant.org.id,
);
assert.equal(stillThree.length, 3);

const paused = await recurringService.setRecurringIssuePaused(tenant.actors.member, {
  orgId: tenant.org.id,
  recurringIssueId: third.id,
  paused: true,
});
assert.equal(paused.paused, true);

await assert.rejects(
  () =>
    recurringService.createRecurringIssue(tenant.actors.member, {
      ...base(tenant.org.id, tenant.project.id),
      title: "Paused still counts",
    }),
  (error: unknown) => error instanceof Error,
);

await assert.rejects(
  () =>
    recurringService.setRecurringIssuePaused(tenant.actors.viewer, {
      orgId: tenant.org.id,
      recurringIssueId: first.id,
      paused: true,
    }),
  (error: unknown) => error instanceof PermissionDeniedError,
);

await assert.rejects(
  () =>
    recurringService.setRecurringIssuePaused(tenant.actors.member, {
      orgId: other.org.id,
      recurringIssueId: first.id,
      paused: true,
    }),
  (error: unknown) => error instanceof TenantScopeError,
);

await assert.rejects(
  () =>
    recurringService.setRecurringIssuePaused(tenant.actors.member, {
      orgId: tenant.org.id,
      recurringIssueId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
      paused: true,
    }),
  (error: unknown) => error instanceof NotFoundError,
);

await assert.rejects(
  () => recurringService.listRecurringIssues(tenant.actors.member, other.org.id),
  (error: unknown) => error instanceof TenantScopeError,
);

const side = await projectRepo.insertProject({
  orgId: tenant.org.id,
  name: "Side",
  slug: "side",
  key: "SIDE",
  description: null,
  visibility: "org",
  leadId: null,
  color: "#6366f1",
  targetDate: null,
});
await projectService.archiveProject(tenant.actors.admin, {
  orgId: tenant.org.id,
  projectId: side.id,
  archiveIssues: false,
});
await assert.rejects(
  () =>
    recurringService.createRecurringIssue(tenant.actors.member, {
      ...base(tenant.org.id, side.id),
      title: "Archived project",
    }),
  (error: unknown) => error instanceof AlreadyArchivedError,
);

const free = await createTenant("freeorg", "free");
await assert.rejects(
  () =>
    recurringService.createRecurringIssue(free.actors.member, {
      ...base(free.org.id, free.project.id),
    }),
  (error: unknown) => error instanceof Error,
);

const enterprise = await createTenant("ent", "enterprise");
for (let i = 0; i < 4; i += 1) {
  await recurringService.createRecurringIssue(enterprise.actors.member, {
    ...base(enterprise.org.id, enterprise.project.id),
    title: `Ent rule ${i} xx`,
    startsOn: "2099-01-01",
  });
}

// Unpause the counting rule we paused? third is paused. first and second are live.
// File first (daily UTC) and second (weekly NY).

const createdIds: string[] = [];
subscribe("issue.created", (payload) => {
  createdIds.push(payload.issueId);
});

const beforeMidnight = await runRecurringIssueJob(new Date("2026-03-01T00:00:00.000Z"));
// UTC midnight of March 1 has started at exactly 00:00Z. Daily rule startsOn 2026-03-01.
assert.equal(beforeMidnight.processed, 1);
assert.equal(beforeMidnight.kind, "recurring-issues");

const again = await runRecurringIssueJob(new Date("2026-03-01T00:00:00.000Z"));
assert.equal(again.processed, 0);

const issues = await issueService.listIssues(tenant.actors.member, {
  orgId: tenant.org.id,
  limit: 50,
});
const filed = issues.items.find((issue) => issue.title === "Daily triage (2026-03-01)");
assert.ok(filed);
assert.equal(filed.status, "backlog");
assert.equal(filed.priority, "high");
assert.equal(filed.description, null);
assert.equal(filed.dueAt, null);
assert.equal(filed.assigneeId, tenant.userIds.admin);
assert.equal(filed.authorId, tenant.userIds.member);
assert.deepEqual([...filed.labelIds], []);
assert.equal(createdIds.length, 1);

const after = await recurringService.listRecurringIssues(tenant.actors.owner, tenant.org.id);
const firstAfter = after.find((rule) => rule.id === first.id);
assert.equal(firstAfter?.lastOccurrenceOn, "2026-03-01");
assert.equal(firstAfter?.paused, false);

// Next calendar day files exactly that day, not a backfill gap.
const next = await runRecurringIssueJob(new Date("2026-03-03T12:00:00.000Z"));
assert.equal(next.processed, 1);
const titles = (
  await issueService.listIssues(tenant.actors.member, {
    orgId: tenant.org.id,
    limit: 50,
  })
).items.map((issue) => issue.title);
