node -e '
const zones = new Set(Intl.supportedValuesOf("timeZone"));
for (const z of ["UTC","utc","GMT","Etc/UTC","America/New_York","US/Eastern","EST"]) {
  let intl = false;
  try { Intl.DateTimeFormat("en-US",{timeZone:z}).format(0); intl = true; } catch {}
  console.log(z, "intl", intl, "supported", zones.has(z));
}
'
